"use strict";(globalThis.webpackChunk_8x8_developer_docs=globalThis.webpackChunk_8x8_developer_docs||[]).push([[65627],{42181:e=>{e.exports=JSON.parse('{"id":"2026-09-03-jvb-video-bridge-port-requirement-corrected","date":"2026-09-03","products":["JaaS"],"product":"JaaS","channel":"","changeType":"Fixed","title":"JVB video bridge port requirement corrected","excerpt":"The technical requirements & whitelists(/jaas/docs/technical-requirements-whitelists) page previously listed TCP port 443 as required for JVB video bridges. That was inaccurate \u2014 JVB media only requires UDP port 10000, and TCP 443 is not a valid destination port for it. The Video Bridges section has been corrected acco\u2026","hasArticle":true,"bodyHtml":"<p>The <a href=\\"/jaas/docs/technical-requirements-whitelists\\">technical requirements &amp; whitelists</a> page previously listed TCP port 443 as required for JVB video bridges. That was inaccurate \u2014 JVB media only requires UDP port 10000, and TCP 443 is not a valid destination port for it. The Video Bridges section has been corrected accordingly.</p>\\n<p>Other TCP/UDP 443 references on the page are unaffected: HTTPS (TCP 443) is still required for the domain whitelists, and TURN relay servers still require TCP 443 and UDP 443.</p>\\n"}')}}]);